PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `catalog_aliases` (
	`namespace` text NOT NULL,
	`identifier` text NOT NULL,
	`product_id` integer NOT NULL,
	PRIMARY KEY(`namespace`, `identifier`),
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_assets` (
	`product_id` integer NOT NULL,
	`kind` text NOT NULL,
	`payload` text NOT NULL,
	PRIMARY KEY(`product_id`, `kind`),
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_brands` (
	`id` integer PRIMARY KEY NOT NULL,
	`name` text NOT NULL
);
CREATE TABLE `catalog_categories` (
	`id` integer PRIMARY KEY NOT NULL,
	`parent_id` integer,
	`level` integer NOT NULL,
	`code` text NOT NULL,
	`name` text NOT NULL,
	FOREIGN KEY (`parent_id`) REFERENCES `catalog_categories`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "catalog_category_shape" CHECK(length("catalog_categories"."code")="catalog_categories"."level"*2 AND "catalog_categories"."code" NOT GLOB '*[^0-9]*' AND "catalog_categories"."level" BETWEEN 1 AND 3),
	CONSTRAINT "catalog_category_parent" CHECK(("catalog_categories"."level"=1 AND "catalog_categories"."parent_id" IS NULL) OR ("catalog_categories"."level">1 AND "catalog_categories"."parent_id" IS NOT NULL))
);
CREATE TABLE `catalog_codes` (
	`code` text PRIMARY KEY NOT NULL,
	`product_id` integer NOT NULL,
	`category_id` integer NOT NULL,
	`is_current` integer NOT NULL,
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`category_id`) REFERENCES `catalog_categories`(`id`) ON UPDATE no action ON DELETE no action,
	CONSTRAINT "catalog_code_shape" CHECK(length("catalog_codes"."code")=12 AND "catalog_codes"."code" NOT GLOB '*[^0-9]*' AND substr("catalog_codes"."code",7,6)!='000000'),
	CONSTRAINT "catalog_code_active" CHECK("catalog_codes"."is_current" IN (0,1))
);
CREATE TABLE `catalog_discounts` (
	`month` text NOT NULL,
	`product_id` integer NOT NULL,
	`regular_price` real,
	`sale_price` real,
	PRIMARY KEY(`month`, `product_id`),
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_documents` (
	`name` text PRIMARY KEY NOT NULL,
	`payload` text NOT NULL
);
CREATE TABLE `catalog_merge_archive` (
	`batch_id` text NOT NULL,
	`table_name` text NOT NULL,
	`row_key` text NOT NULL,
	`payload` text NOT NULL,
	PRIMARY KEY(`batch_id`, `table_name`, `row_key`),
	FOREIGN KEY (`batch_id`) REFERENCES `catalog_merge_runs`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_merge_runs` (
	`id` text PRIMARY KEY NOT NULL,
	`from_version` text NOT NULL,
	`to_version` text NOT NULL,
	`status` text NOT NULL,
	`guard` integer NOT NULL,
	`created_at` text NOT NULL,
	`applied_at` text,
	CONSTRAINT "catalog_merge_guard" CHECK("catalog_merge_runs"."guard"=1),
	CONSTRAINT "catalog_merge_status" CHECK("catalog_merge_runs"."status" IN ('prepared','applied'))
);
CREATE TABLE `catalog_prices` (
	`product_id` integer NOT NULL,
	`kind` text NOT NULL,
	`amount` real NOT NULL,
	PRIMARY KEY(`product_id`, `kind`),
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_products` (
	`id` integer PRIMARY KEY NOT NULL,
	`slug` text NOT NULL,
	`name` text NOT NULL,
	`brand_id` integer NOT NULL,
	`category_id` integer NOT NULL,
	`tax_type` text NOT NULL,
	`sort_order` integer NOT NULL,
	`visible` integer NOT NULL,
	FOREIGN KEY (`brand_id`) REFERENCES `catalog_brands`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`category_id`) REFERENCES `catalog_categories`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_records` (
	`product_id` integer NOT NULL,
	`kind` text NOT NULL,
	`payload` text NOT NULL,
	PRIMARY KEY(`product_id`, `kind`),
	FOREIGN KEY (`product_id`) REFERENCES `catalog_products`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_sequences` (
	`category_id` integer PRIMARY KEY NOT NULL,
	`last_sequence` integer NOT NULL,
	FOREIGN KEY (`category_id`) REFERENCES `catalog_categories`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `catalog_state` (
	`key` text PRIMARY KEY NOT NULL,
	`value` text NOT NULL
);
CREATE TABLE `catalog_texts` (
	`id` integer PRIMARY KEY NOT NULL,
	`value` text NOT NULL
);
CREATE TABLE `coupang_price_current` (
	`product_slug` text PRIMARY KEY NOT NULL,
	`product_id` text,
	`item_id` text,
	`vendor_item_id` text,
	`normalized_name` text NOT NULL,
	`normalized_spec` text NOT NULL,
	`normalized_quantity` text NOT NULL,
	`displayed_price` integer NOT NULL,
	`shipping_fee` integer,
	`seller` text,
	`price_condition` text,
	`source_url` text NOT NULL,
	`match_score` integer NOT NULL,
	`checked_at` text NOT NULL,
	`last_history_id` integer NOT NULL
, `comparison_quantity` integer, `comparison_basis` text, `catalog_product_key` integer REFERENCES catalog_products(id));
CREATE TABLE `daily_visits` (
	`day` text NOT NULL,
	`visitor` text NOT NULL,
	PRIMARY KEY(`day`, `visitor`)
);
CREATE TABLE `feedback_posts` (
	`id` text PRIMARY KEY NOT NULL,
	`category` text NOT NULL,
	`title` text NOT NULL,
	`body` text NOT NULL,
	`nickname` text NOT NULL,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	`deleted_at` integer,
	`edit_hash` text NOT NULL,
	`creator` text NOT NULL
);
CREATE TABLE `price_history` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`product_slug` text NOT NULL,
	`observation_id` text,
	`entry_kind` text NOT NULL,
	`original_history_id` integer,
	`attempted_at` text NOT NULL,
	`observed_at` text,
	`source_url` text,
	`observed_title` text,
	`observed_option` text,
	`observed_spec` text,
	`observed_quantity` text,
	`observed_price` integer,
	`shipping_fee` integer,
	`seller` text,
	`price_condition` text,
	`match_score` integer,
	`match_reasons` text,
	`hard_mismatch` integer,
	`change_percent` real,
	`status` text NOT NULL,
	`reason` text,
	`reviewer` text,
	`reviewed_at` text,
	`created_at` text NOT NULL
, `product_id` text, `item_id` text, `vendor_item_id` text, `comparison_quantity` integer, `comparison_basis` text, `search_card` text, `catalog_product_key` integer REFERENCES catalog_products(id));
CREATE TABLE `price_update_queue` (
	`product_slug` text PRIMARY KEY NOT NULL,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`priority` integer DEFAULT 0 NOT NULL,
	`attempts` integer DEFAULT 0 NOT NULL,
	`last_attempt_at` text,
	`next_attempt_at` text,
	`lock_expires_at` text,
	`last_checked_at` text,
	`last_error` text,
	`created_at` text NOT NULL,
	`updated_at` text NOT NULL
, `catalog_product_key` integer REFERENCES catalog_products(id));
CREATE TABLE `product_interest_daily` (
	`day` text NOT NULL,
	`product_slug` text NOT NULL,
	`favorite_adds` integer DEFAULT 0 NOT NULL,
	`shopping_adds` integer DEFAULT 0 NOT NULL, `catalog_product_key` integer REFERENCES catalog_products(id),
	PRIMARY KEY(`day`, `product_slug`)
);
CREATE TABLE `shopping_shares` (
	`id` text PRIMARY KEY NOT NULL,
	`items` text NOT NULL,
	`created_at` integer NOT NULL,
	`expires_at` integer NOT NULL,
	`creator` text NOT NULL
);
CREATE INDEX `price_history_product_time_idx` ON `price_history` (`product_slug`,`attempted_at`);
CREATE INDEX `price_history_status_idx` ON `price_history` (`status`);
CREATE UNIQUE INDEX `price_history_observation_uidx` ON `price_history` (`observation_id`);
CREATE INDEX `price_queue_ready_idx` ON `price_update_queue` (`status`,`next_attempt_at`,`priority`);
CREATE INDEX `price_queue_lock_idx` ON `price_update_queue` (`status`,`lock_expires_at`);
CREATE INDEX `product_interest_product_day_idx` ON `product_interest_daily` (`product_slug`,`day`);
CREATE INDEX `catalog_alias_product_idx` ON `catalog_aliases` (`product_id`);
CREATE UNIQUE INDEX `catalog_brands_name_unique` ON `catalog_brands` (`name`);
CREATE UNIQUE INDEX `catalog_categories_code_unique` ON `catalog_categories` (`code`);
CREATE UNIQUE INDEX `catalog_one_current_code` ON `catalog_codes` (`product_id`) WHERE "catalog_codes"."is_current" = 1;
CREATE UNIQUE INDEX `catalog_products_slug_unique` ON `catalog_products` (`slug`);
CREATE INDEX `catalog_product_category_idx` ON `catalog_products` (`category_id`);
CREATE UNIQUE INDEX `catalog_texts_value_unique` ON `catalog_texts` (`value`);
CREATE TRIGGER catalog_link_coupang_price_current_insert AFTER INSERT ON coupang_price_current BEGIN UPDATE coupang_price_current SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_coupang_price_current_slug_update AFTER UPDATE OF product_slug ON coupang_price_current BEGIN UPDATE coupang_price_current SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_price_history_insert AFTER INSERT ON price_history BEGIN UPDATE price_history SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_price_history_slug_update AFTER UPDATE OF product_slug ON price_history BEGIN UPDATE price_history SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_price_update_queue_insert AFTER INSERT ON price_update_queue BEGIN UPDATE price_update_queue SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_price_update_queue_slug_update AFTER UPDATE OF product_slug ON price_update_queue BEGIN UPDATE price_update_queue SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_product_interest_daily_insert AFTER INSERT ON product_interest_daily BEGIN UPDATE product_interest_daily SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE TRIGGER catalog_link_product_interest_daily_slug_update AFTER UPDATE OF product_slug ON product_interest_daily BEGIN UPDATE product_interest_daily SET catalog_product_key=(SELECT id FROM catalog_products WHERE slug=NEW.product_slug) WHERE rowid=NEW.rowid; END;
CREATE INDEX `shopping_shares_creator_time_idx` ON `shopping_shares` (`creator`,`created_at`);
CREATE INDEX `shopping_shares_expiry_idx` ON `shopping_shares` (`expires_at`);
CREATE INDEX `feedback_posts_created_idx` ON `feedback_posts` (`created_at`,`id`);
CREATE INDEX `feedback_posts_creator_idx` ON `feedback_posts` (`creator`,`created_at`);
DELETE FROM "sqlite_sequence";
COMMIT;
PRAGMA foreign_keys=ON;
