INSERT INTO "catalog_texts" VALUES(13197,'2026년 기준 가격표·촬영일 미표기');
INSERT INTO "catalog_texts" VALUES(13198,'제시된 2026년 기준 면세주류 가격표의 금액입니다. 일반 주류 상품의 PX가와 별도로 기록했으며, 현재 매장 가격·취급 여부·구매 자격과 한도는 매장에서 확인하세요.');
